  .input(z.object({ table: z.string(), database, column: z.string(), offset: z.number(), limit: z.number() }))
  .output(z.object({ copied: z.number() }))
  .runner(local)
  .effect('repeatable')
  .run(async (input, ctx) => {
    const result = await ctx.exec([
      'backfill',
      'copy',
      input.database,
      input.table,
      input.column,
      '--offset',
      String(input.offset),
      '--limit',
      String(input.limit),
    ]);
    return { copied: Number(result.stdout.trim()) };
  });

